$p = 'C:\Users\蔚邦成\Documents\Codex\2026-07-17\wo-d\outputs\skin-diagnosis\index.html'
Remove-Item $p -Force -ErrorAction SilentlyContinue
Add-Content $p '<!DOCTYPE html><html lang=zh-CN><head><style>:root{--p:#2d6a4f;--pl:#40916c;--pb:#e8f5e9;--a:#ff6b6b;--al:#ffe8e8;--w:#e67e22;--wb:#fef3e2;--d:#c0392b;--db:#fde8e8;--g1:#fafafa;--g2:#f5f5f5;--g3:#e5e5e5;--g4:#d4d4d4;--g5:#a3a3a3;--g6:#737373;--g7:#525252;--g8:#404040;--g9:#262626;--g10:#171717;--r:12px;--mw:640px;--f:-apple-system,PingFang SC,Noto Sans SC,Microsoft YaHei,sans-serif}*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}html{font-size:16px}body{font-family:var(--f);background:var(--g1);color:var(--g9);min-height:100vh;display:flex;align-items:center;flex-direction:column}.c{width:100%;max-width:var(--mw);padding:20px;min-height:100vh}.hd{text-align:center;padding:24px 0}.hd .lg{font-size:13px;color:var(--p);font-weight:600;letter-spacing:2px}.hd h1{font-size:22px;font-weight:700;color:var(--g10)}.hd p{font-size:14px;color:var(--g6);margin-top:4px}.pb{background:var(--g3);height:6px;border-radius:3px;margin:8px 0 16px;overflow:hidden}.pb-bar{height:100%;background:linear-gradient(90deg,var(--p),var(--pl));border-radius:3px;transition:width .5s;width:0%}.pb-l{font-size:12px;color:var(--g6);text-align:right}.cd{background:#fff;border-radius:var(--r);padding:24px;box-shadow:0 1px 3px rgba(0,0,0,.06);margin-bottom:16px;display:none}.cd.a{display:block;animation:in .35s}@keyframes in{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.cd h2{font-size:18px;color:var(--g10);margin-bottom:4px}.cd .st{font-size:13px;color:var(--g6);margin-bottom:16px}.it{background:var(--db);border:1px solid var(--d);border-radius:var(--r);padding:16px;margin:0 0 16px;display:none}.it.s{display:block}.it h3{color:var(--d);font-size:15px;margin-bottom:6px}.it p{font-size:13px;color:var(--g8);line-height:1.6}.it.w{background:var(--wb);border-color:var(--w)}.it.w h3{color:var(--w)}.q{margin-bottom:16px}.ql{font-size:14px;font-weight:600;color:var(--g9);margin-bottom:8px}.ops{display:flex;flex-direction:column;gap:8px}.op{display:flex;align-items:center;padding:12px 16px;border:1.5px solid var(--g3);border-radius:8px;cursor:pointer;font-size:14px;gap:10px;user-select:none;transition:all .2s}.op:hover{border-color:var(--pl);background:var(--pb)}.op.s{border-color:var(--p);background:var(--pb);font-weight:600}.op .cb{width:20px;height:20px;border:2px solid var(--g4);border-radius:4px;flex-shrink:0;display:flex;align-items:center;justify-content:center}.op.s .cb{background:var(--p);border-color:var(--p)}.op .rb{width:20px;height:20px;border:2px solid var(--g4);border-radius:50%;flex-shrink:0}.op.s .rb{border-color:var(--p)}.bg{display:flex;gap:12px;margin-top:20px}.btn{flex:1;padding:14px 24px;border:none;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;font-family:var(--f)}.btn-p{background:var(--p);color:#fff}.btn-p:hover{background:var(--pl)}.in{text-align:center;padding:40px 0}.in h2{font-size:24px;font-weight:700;color:var(--g10);margin-bottom:8px}.in p{font-size:14px;color:var(--g6);line-height:1.6;max-width:480px;margin:0 auto 24px}.in .fs{display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:left;max-width:400px;margin:0 auto 24px}.in .fs .ft{font-size:13px;color:var(--g7);padding:8px 12px;background:var(--g2);border-radius:6px}.in .dc{font-size:11px;color:var(--g5)}.rs{margin-bottom:20px}.rsum{background:linear-gradient(135deg,var(--p),#1b4332);color:#fff;border-radius:var(--r);padding:20px;margin-bottom:16px}.pc{background:#fff;border:1px solid var(--g3);border-radius:var(--r);padding:16px;margin-bottom:12px}.pc .pd{background:#e8f5e9;border-radius:6px;padding:8px 12px;margin:6px 0;font-size:13px;color:#2d6a4f}.pc .px{background:var(--al);border-radius:6px;padding:8px 12px;margin:6px 0;font-size:13px;color:var(--d)}.ld{display:none;text-align:center;padding:60px 0;flex-direction:column;align-items:center}.ld.a{display:flex}.ld .sp{width:40px;height:40px;border:4px solid var(--g3);border-top-color:var(--p);border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.ld p{font-size:14px;color:var(--g6)}@media(max-width:480px){.c{padding:16px}.cd{padding:20px}.in .fs{grid-template-columns:1fr}.bg{flex-direction:column}}</style></head><body><div class=c>' -Encoding UTF8
<div class=hd><div class=lg>Skin Diagnosis</div><h1>痘痘皮肤⾃测诊断</h1><p>6步找到你的痘痘类型与解决方案</p></div><div class=pb><div class=pb-bar id=pb></div></div><div class=pb-l id=pbl>开始测试</div>
<div class=cd id=intro><div class=in><h2>你的痘痘到底是什么原因</h2><p>不是所有的痘痘都该刷酸。6步科学⾃测找到真正的原因拿到针对性的解决方案。</p><div class=fs><div class=ft>3-5分钟完成</div><div class=ft>专业级判断逻辑</div><div class=ft>分阶段行动方案</div><div class=ft>就医指征提醒</div></div><button class=btn onclick=startTest()>开始⾃测</button><div class=dc>*本测试不能替代医生诊断</div></div></div><div id=stages></div><div class=it id=intercept></div><div class=ld id=loading><div class=sp></div><p>正在分析你的皮肤状况</p><div class=ls>匹配症状特征...</div></div><div id=result></div>
<script>function startTest(){document.getElementById("intro").style.display="none";showQuestion(0)}var questions=[{q:"你主要在哪些位置长痘?",opts:[{l:"额头",v:"forehead"},{l:"脸颊",v:"cheek"},{l:"下巴",v:"chin"},{l:"下颌线",v:"jawline"},{l:"全脸弥散",v:"allover"}]},{q:"痘痘的形态?",opts:[{l:"闭口/粉刺",v:"closed"},{l:"红肿痘",v:"inflamed"},{l:"脓包",v:"pustule"},{l:"囊肿/结节",v:"cyst"}]},{q:"有没有以下规律?",opts:[{l:"月经前后加重(限⼥性)",v:"menstrual"},{l:"压力大/熬夜后加重",v:"stress"},{l:"吃甜食/牛奶后加重",v:"diet"},{l:"换季加重",v:"season"}]},{q:"你长痘多久了?",opts:[{l:"刚长⼏周",v:"weeks"},{l:"反复几个月",v:"months"},{l:"断断续续好几年",v:"years"}]},{q:"之前用过哪些方法?(选效果最好的)",opts:[{l:"⽔杨酸/壬⼆酸",v:"acid"},{l:"过氧化苯甲酰",v:"bp"},{l:"维A酸/阿达帕林",v:"retinoid"},{l:"没有/其他",v:"none"}]},{q:"你喝牛奶/吃甜食多吗?",opts:[{l:"每天",v:"daily"},{l:"每周几次",v:"often"},{l:"偶尔",v:"occasional"}]},{q:"睡眠与压力?",opts:[{l:"睡眠足/压⼒小",v:"good"},{l:"睡眠不足/压⼒大",v:"bad"},{l:"作息不规律",v:"irregular"}]}];var currentQ=0;var answers={};function showQuestion(i){var s=document.getElementById("stages");if(i>=questions.length){analyze();return}var q=questions[i];var h="<div class=cd.a><h2>第"+(i+1)+"步</h2><div class=st>"+q.q+"</div><div class=ops>";for(var j=0;j<q.opts.length;j++){h+="<div class=op onclick=selectAnswer("+i+","+j+")><div class=rb></div><span>"+q.opts[j].l+"</span></div>"}h+="</div><div class=bg><button class=btn-p onclick=nextQuestion("+i+")>下一步</button></div></div>";s.innerHTML=h;document.getElementById("pb").style.width=(i/questions.length*85)+"%";document.getElementById("pbl").textContent="步骤"+(i+1)+"/"+questions.length}function selectAnswer(qi,oi){answers[qi]=oi;var ops=document.getElementById("stages").querySelectorAll(".op");for(var j=0;j<ops.length;j++)ops[j].classList.remove("s");ops[oi].classList.add("s")}function nextQuestion(i){if(answers[i]===undefined){alert("请选择一个选项");return}currentQ++;showQuestion(currentQ)}function analyze(){document.getElementById("stages").innerHTML="";document.getElementById("loading").classList.add("a");setTimeout(function(){document.getElementById("loading").classList.remove("a");showResult()},2000)}function showResult(){var r=document.getElementById("result");r.style.display="block";var h="<div class=rsum><h2>分析结果</h2><p>根据你的回答建议优先关注屏障修护和抗炎。</p></div><div class=pc><div class=pd>✅建议使用：氨基酸洁面 + B5修护 + 壬二酸局部点涂</div><div class=px>❌暂停使用：酸类、A醇、磨砂产品、荷荷巴油</div></div><div class=pc><div class=pd><b>阶段一（第1-2周）：</b>纯修护，停用所有功能产品</div><div class=pd><b>阶段二（第3-5周）：</b>修护打底 + 壬二酸局部点涂</div><div class=pd><b>阶段三（第6-12周）：</b>逐步恢复完整护肤流程</div></div>";r.innerHTML=h;document.getElementById("pb").style.width="100%";document.getElementById("pbl").textContent="诊断完成"}</script></div></body></html>
